// Retrieve data from RSS feed and Google Sheets
const rssItems = items; // Contains RSS articles
const sheetItems = $items("Set field - existing_url", 0);

// Extract the links of articles present in Google Sheets
const existingUrls = sheetItems.map(entry => entry.json.existing_url);

// Filter RSS articles to keep only those not present in Google Sheets
const newArticles = rssItems.filter(rssItem => {
    return !existingUrls.includes(rssItem.json.link);
});

// If new articles are found, return them
if (newArticles.length > 0) {
    return newArticles;
}

// If no new articles, return an informational message
return [{ json: { message: "No new articles found." } }];

// Fetch the prompt text
const prompt = $('SetPrompt').first().json.data;  // Ensure the prompt contains placeholders like {{ some.node.value }}

// Example variables object
const variables = {
  company: $('setVars').first().json.company,
  features: "Awesome Software",
  keyword: "2025-02-07"
};

// Function to replace placeholders dynamically
const replaceVariables = (text, vars) => {
  return text.replace(/{{(.*?)}}/g, (match, key) => {
    const trimmedKey = key.trim();

    // Extract last part after the last dot
    const finalKey = trimmedKey.split('.').pop();

    // Replace if key exists, otherwise leave placeholder unchanged
    return vars.hasOwnProperty(finalKey) ? vars[finalKey] : match;
  });
};

// Replace and return result
return [{
  prompt: replaceVariables(prompt, variables)
}];

